```ts
import * as THREE from 'three';
import {
  hazardsFor,
  HAZARD_RENDER_RANGE_M,
  type Hazard,
  type HazardKind,
} from '@shared/world/hazards';
import type { SystemGen } from '@shared/galaxy/types';

/** One hazard disc placement (pure data, mirrors the shared Hazard). */
export interface HazardDiscPlacement {
  hazardId: string;
  kind: HazardKind; // only 'storm' | 'radzone' (drone cells have no disc)
  x: number; y: number; z: number;
  radius: number;
  intensity: number;
}

/**
 * Pure: hazard discs of the system — hazardsFor (the same shared function the server uses)
 * minus the drone cells (their threat IS the drone itself).
 */
export function hazardDiscsFor(seed, system): HazardDiscPlacement[] {
  return hazardsFor(seed, system)
    .filter((h) => h.kind !== 'drones')
    .map((h) => ({ hazardId: h.hazardId, kind: h.kind, x: h.pos.x, y: h.pos.y, z: h.pos.z, radius: h.radius, intensity: h.intensity }));
}

/** Pure: 500 m cull (same rule as padRingVisible). */
export function hazardDiscVisible(pos: Vec3 | null, discPos: {x,y,z}): boolean {
  if (!pos) return false;
  return Math.hypot(pos.x - discPos.x, pos.y - discPos.y, pos.z - discPos.z) <= HAZARD_RENDER_RANGE_M;
}

export interface HazardDiscRender {
  /** The group to attach to the per-system world group (disposal comes along with it). */
  group: THREE.Group;
  /** The cell center (cull anchor). */
  center: THREE.Vector3;
