private renderDrone(
  id: string,
  info: RemoteInfo,
  state: RemoteRenderState,
  now: number,
): void {
  let r = this.drones.get(id);
  if (!r) {
    const built = buildDroneMesh();
    this.parent?.add(built.group);
    r = built;
    this.drones.set(id, r);
    registerEntity(id, 'drone');
  }
  r.group.position.set(state.pos.x, state.pos.y, state.pos.z);
