  r.group.visible = (info.hull ?? 1) > 0;
  const opacity = state.dimmed ? DIMMED_OPACITY : state.stale ? STALE_OPACITY : 1;
  r.body.opacity = opacity;
  r.glow.opacity = 0.3 * opacity;
}

