 * scanning seeded systems (hazardsFor is a pure function of the seed, so
 * this scan is stable run-to-run).
 */
function systemWithAllKinds(): { system: ReturnType<typeof generateSystem>; hazards: ReturnType<typeof hazardsFor> } {
  const stars = generateStars(SEED, 24);
