import { describe, expect, it } from 'vitest';
import { generateStars } from './src/shared/galaxy/stars';
import { generateSystem } from './src/shared/galaxy/system';
import { hazardsFor } from './src/shared/world/hazards';

describe('probe', () => {
  it('prints hazards for the default seed', () => {
    const SEED = 'DRIFT-SEED-0001';
    const stars = generateStars(SEED, 8);
    for (let i = 0; i < Math.min(4, stars.length); i++) {
      const sys = generateSystem(SEED, stars[i].id);
      const hz = hazardsFor(SEED, sys);
      const kinds = hz.reduce((m: Record<string, number>, h) => ((m[h.kind] = (m[h.kind] || 0) + 1), m), {});
      console.log(`sys[${i}] ${sys.systemId} planets=${sys.planets.length} hazards=${hz.length} ${JSON.stringify(kinds)}`);
    }
    const home = generateSystem(SEED, stars[0].id);
    const hz = hazardsFor(SEED, home);
    console.log('HOME hazards:', hz.length, hz.map((h) => h.kind));
    expect(true).toBe(true);
  });
});

